package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.in.ListActiveLoansUseCase.ActiveLoanPage;
import com.example.lending.application.port.in.ListActiveLoansUseCase.ActiveLoanView;
import com.example.lending.application.port.out.LoadActiveLoanPagePort;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Component
public class ActiveLoanQueryAdapter implements LoadActiveLoanPagePort {

    private final LoanJpaRepository loanJpaRepository;
    private final BookJpaRepository bookJpaRepository;

    public ActiveLoanQueryAdapter(LoanJpaRepository loanJpaRepository, BookJpaRepository bookJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
        this.bookJpaRepository = bookJpaRepository;
    }

    @Override
    public ActiveLoanPage loadActiveLoanPage(UUID memberId, int page, int size) {
        // 정렬 키가 같은 대출이 페이지 경계에서 흔들리지 않도록 id 로 한 번 더 정렬한다.
        Sort sort = Sort.by("loanedAt").ascending().and(Sort.by("id"));
        Page<LoanJpaEntity> loans = loanJpaRepository.findByMemberIdAndReturnedAtIsNull(
                memberId, PageRequest.of(page, size, sort));

        Set<UUID> bookIds = loans.getContent().stream()
                .map(LoanJpaEntity::getBookId)
                .collect(Collectors.toSet());
        Map<UUID, String> titles = bookJpaRepository.findAllById(bookIds).stream()
                .collect(Collectors.toMap(BookJpaEntity::getId, BookJpaEntity::getTitle));

        var items = loans.getContent().stream()
                .map(loan -> new ActiveLoanView(loan.getId(), loan.getBookId(), titles.get(loan.getBookId()),
                        loan.getLoanedAt(), loan.getDueAt()))
                .toList();
        return new ActiveLoanPage(items, page, size, loans.getTotalElements());
    }
}
