                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        String bookId = objectMapper.readTree(bookBody).get("id").asText();

        String loanBody = objectMapper.writeValueAsString(Map.of(
                "bookId", bookId, "memberId", memberId, "loanedAt", loanedAt));
        String loanResponse = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanBody))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loanResponse).get("loanId").asText();
    }

    private String registerMember() throws Exception {
        String body = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"정하윤\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(body).get("memberId").asText();
    }
